CREATE TABLE public.lesson_views(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,profile_role public.profile_role NOT NULL,lesson_id uuid NOT NULL REFERENCES public.lessons(id),seconds_watched integer NOT NULL,viewed_on date NOT NULL DEFAULT current_date,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.lesson_views TO service_role; ALTER TABLE public.lesson_views ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.record_lesson_view(_lesson uuid,_seconds integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR public.current_profile_role() NOT IN ('estudante','geral','colaborador') OR _seconds<0 OR _seconds>86400 THEN RAISE EXCEPTION 'Visualização inválida'; END IF; IF NOT EXISTS(SELECT 1 FROM public.lessons l JOIN public.courses c ON c.id=l.course_id WHERE l.id=_lesson AND c.published AND c.status='publicado') THEN RAISE EXCEPTION 'Aula indisponível'; END IF; INSERT INTO public.lesson_views(user_id,profile_role,lesson_id,seconds_watched) VALUES(auth.uid(),public.current_profile_role(),_lesson,_seconds); END $$;
CREATE TABLE public.fund_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),preset text NOT NULL DEFAULT 'tracao',audience_weight numeric NOT NULL DEFAULT .55,production_weight numeric NOT NULL DEFAULT .25,completion_weight numeric NOT NULL DEFAULT .20,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(audience_weight+production_weight+completion_weight=1));
GRANT SELECT,UPDATE ON public.fund_settings TO authenticated; GRANT ALL ON public.fund_settings TO service_role; ALTER TABLE public.fund_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY fund_settings_read ON public.fund_settings FOR SELECT TO authenticated USING(true); CREATE POLICY fund_settings_admin ON public.fund_settings FOR UPDATE TO authenticated USING(public.is_admin() AND public.current_profile_role() NOT IN ('professor','ies','empresa','colaborador')) WITH CHECK(public.is_admin());
INSERT INTO public.fund_settings DEFAULT VALUES;
CREATE TABLE public.monthly_funds(month date PRIMARY KEY,total_revenue_cents bigint NOT NULL,teacher_fund_cents bigint NOT NULL,ies_fund_cents bigint NOT NULL,weights jsonb NOT NULL,closed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.monthly_funds TO authenticated; GRANT ALL ON public.monthly_funds TO service_role; ALTER TABLE public.monthly_funds ENABLE ROW LEVEL SECURITY; CREATE POLICY monthly_funds_admin ON public.monthly_funds FOR SELECT TO authenticated USING(public.is_admin());
CREATE TABLE public.author_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),month date NOT NULL REFERENCES public.monthly_funds(month),owner_id uuid NOT NULL,fund_type text NOT NULL CHECK(fund_type IN('professor','ies')),audience numeric NOT NULL,production numeric NOT NULL,completion numeric NOT NULL,final_score numeric NOT NULL,amount_cents bigint NOT NULL,payment_status text NOT NULL DEFAULT 'pendente',UNIQUE(month,owner_id,fund_type));
GRANT SELECT ON public.author_scores TO authenticated; GRANT ALL ON public.author_scores TO service_role; ALTER TABLE public.author_scores ENABLE ROW LEVEL SECURITY; CREATE POLICY author_scores_read ON public.author_scores FOR SELECT TO authenticated USING((fund_type='professor' AND owner_id=auth.uid() AND public.current_profile_role()='professor') OR (fund_type='ies' AND public.organization_member(owner_id,'ies')) OR public.is_admin());
CREATE TABLE public.payout_accounts(owner_id uuid NOT NULL,owner_type text NOT NULL CHECK(owner_type IN('professor','ies')),holder_name text NOT NULL,bank_code text NOT NULL,branch text NOT NULL,account text NOT NULL,pix_key text,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,owner_type));
GRANT SELECT ON public.payout_accounts TO authenticated; GRANT ALL ON public.payout_accounts TO service_role; ALTER TABLE public.payout_accounts ENABLE ROW LEVEL SECURITY; CREATE POLICY payout_read ON public.payout_accounts FOR SELECT TO authenticated USING((owner_type='professor' AND owner_id=auth.uid() AND public.current_profile_role()='professor') OR (owner_type='ies' AND public.organization_permission(owner_id,'ies','bancarios')));
CREATE OR REPLACE FUNCTION public.save_payout_account(_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; kind text; BEGIN kind:=public.current_profile_role()::text; IF kind='professor' THEN owner:=auth.uid(); ELSIF kind='ies' THEN SELECT institution_id INTO owner FROM public.profiles WHERE id=auth.uid(); IF NOT public.organization_permission(owner,'ies','bancarios') THEN RAISE EXCEPTION 'Permissão bancária necessária'; END IF; ELSE RAISE EXCEPTION 'Acesso negado'; END IF; IF length(trim(COALESCE(_payload->>'holder_name','')))<2 OR length(trim(COALESCE(_payload->>'bank_code','')))<3 OR length(trim(COALESCE(_payload->>'branch','')))<1 OR length(trim(COALESCE(_payload->>'account','')))<2 THEN RAISE EXCEPTION 'Dados bancários incompletos'; END IF; INSERT INTO public.payout_accounts VALUES(owner,kind,trim(_payload->>'holder_name'),trim(_payload->>'bank_code'),trim(_payload->>'branch'),trim(_payload->>'account'),NULLIF(trim(_payload->>'pix_key'),''),now()) ON CONFLICT(owner_id,owner_type) DO UPDATE SET holder_name=EXCLUDED.holder_name,bank_code=EXCLUDED.bank_code,branch=EXCLUDED.branch,account=EXCLUDED.account,pix_key=EXCLUDED.pix_key,updated_at=now(); INSERT INTO public.activity_logs(user_id,organization_id,organization_type,action,entity) VALUES(auth.uid(),CASE WHEN kind='ies' THEN owner END,CASE WHEN kind='ies' THEN 'ies' END,'dados_bancarios_alterados','payout_accounts'); END $$;
REVOKE ALL ON FUNCTION public.record_lesson_view(uuid,integer),public.save_payout_account(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_lesson_view(uuid,integer),public.save_payout_account(jsonb) TO authenticated;